func (q *Queries) UpdateRuntimeNode(ctx context.Context, arg UpdateRuntimeNodeParams) (RuntimeNode, error) {
	row := q.db.QueryRow(ctx, updateRuntimeNode,
		arg.ID,
		arg.Name,
		arg.MaxActive,
		arg.MaxRetained,
	)
	var i RuntimeNode
	err := row.Scan(
		&i.ID,
		&i.InstallationID,
		&i.Name,
		&i.BackendFingerprint,
		&i.CredentialSha256,
		&i.MaxActive,
		&i.MaxRetained,
		&i.ConnectionID,
		&i.ProviderReady,
		&i.Health,
		&i.ConnectedEpoch,
		&i.LastSeenAt,
		&i.CreatedAt,
		&i.RemovedAt,
		&i.SpecificationDigest,
		&i.DeploymentGeneration,
		&i.CoreUrl,
		&i.EnrollmentID,
		&i.ReadyGeneration,
		&i.ProtocolVersion,
	)
	return i, err
}
